# Fixed rubrics, in display order. Mirrors publications.models.rubric.RubricCode.
RUBRIC_CODES = ["HOUSING", "PARKS_GARDENS", "PUBLIC_SPACE", "HERITAGE"]

# The old single category each project had, and the rubric it becomes.
CATEGORY_TO_RUBRIC = {
    "ENVIRONMENT": "PARKS_GARDENS",
    "LIVING_ENVIRONMENT": "PUBLIC_SPACE",
    "URBAN_FORMS": "HOUSING",
}
FALLBACK_RUBRIC = "PUBLIC_SPACE"


def create_rubrics(apps, schema_editor):
    Rubric = apps.get_model("publications", "Rubric")
    for sort_order, code in enumerate(RUBRIC_CODES):
        Rubric.objects.update_or_create(code=code, defaults={"sort_order": sort_order})


def categories_to_rubrics(apps, schema_editor):
    """Give every project the rubric matching its old category.

    Revisions are rewritten too (``rubrics`` as a list of ids, ``category``
    dropped), so publishing a pending draft or reverting keeps the rubric
    instead of clearing it.
    """
    Rubric = apps.get_model("publications", "Rubric")
    ProjectPage = apps.get_model("publications", "ProjectPage")
    rubric_ids = dict(Rubric.objects.values_list("code", "id"))

    def rubric_for(category):
        return rubric_ids[CATEGORY_TO_RUBRIC.get(category, FALLBACK_RUBRIC)]

    for page_id, category in ProjectPage.objects.values_list("pk", "category"):
        ProjectPage.rubrics.through.objects.get_or_create(
            projectpage_id=page_id, rubric_id=rubric_for(category)
        )

    ContentType = apps.get_model("contenttypes", "ContentType")
    Revision = apps.get_model("wagtailcore", "Revision")
    content_type = ContentType.objects.filter(app_label="publications", model="projectpage").first()
    if content_type is None:
        return

    for revision in Revision.objects.filter(content_type=content_type).iterator():
        if rubrics_in_revision(revision.content, rubric_for):
            revision.save(update_fields=["content"])


def rubrics_in_revision(content, rubric_for):
    """Swap ``category`` for ``rubrics`` in a revision's content; False if already done."""
    if "category" not in content and "rubrics" in content:
        return False
    content["rubrics"] = [rubric_for(content.pop("category", None))]
    return True


